#!/usr/bin/env node
/**
 * Generate the service-worker asset manifest from the real application shell.
 *
 * Sutra intentionally has no bundler.  Keeping this small generated artifact
 * means the HTML entry point remains the load-order authority while the
 * service worker and deploy verifier consume the same deterministic list.
 */
import { readFileSync, writeFileSync, readdirSync } from 'node:fs';
import { resolve } from 'node:path';
import vm from 'node:vm';

const root = resolve(process.cwd());
const shellFile = 'Sutra.html';
const html = readFileSync(resolve(root, shellFile), 'utf8');

function normalizeLocalReference(raw) {
  const value = String(raw || '').trim();
  if (!value || value.startsWith('#') || value.startsWith('//')) return null;
  if (/^(?:https?:|data:|blob:|mailto:|tel:)/i.test(value)) return null;
  const withoutFragment = value.split('#')[0];
  if (!withoutFragment) return null;
  return withoutFragment.startsWith('./') ? withoutFragment : `./${withoutFragment}`;
}

function collectReferences() {
  const critical = new Set([`./${shellFile}`, './manifest.webmanifest']);
  const optional = new Set();
  const tagPattern = /<(script|link)\b[^>]*>/gi;
  let match;
  while ((match = tagPattern.exec(html))) {
    const tag = match[0];
    const attr = match[1].toLowerCase() === 'script' ? 'src' : 'href';
    const attrMatch = tag.match(new RegExp(`\\b${attr}\\s*=\\s*["']([^"']+)["']`, 'i'));
    if (!attrMatch) continue;
    const reference = normalizeLocalReference(attrMatch[1]);
    if (!reference) continue;
    if (match[1].toLowerCase() === 'script' || /\brel\s*=\s*["'][^"']*(?:stylesheet|manifest)[^"']*["']/i.test(tag)) {
      critical.add(reference);
    } else if (/\brel\s*=\s*["'][^"']*(?:icon|apple-touch-icon)[^"']*["']/i.test(tag)) {
      optional.add(reference);
    }
  }
  // The native PDF workspace dynamically imports PDF.js and requests its
  // worker, character maps, and standard fonts at runtime. They do not appear
  // as HTML tags, so enumerate the pinned local runtime explicitly to make a
  // fresh installed PWA fully PDF-capable while offline.
  const pdfRuntimeRoots = [
    'assets/vendor/pdfjs/build',
    'assets/vendor/pdfjs/cmaps',
    'assets/vendor/pdfjs/standard_fonts'
  ];
  pdfRuntimeRoots.forEach((directory) => {
    readdirSync(resolve(root, directory), { withFileTypes: true }).forEach((entry) => {
      if (!entry.isFile() || !/\.(?:m?js|bcmap|pfb|ttf)$/i.test(entry.name)) return;
      critical.add(`./${directory}/${entry.name}`);
    });
  });
  // pdf-lib and fontkit are intentionally loaded only when page assembly or
  // export is requested, but installed PWAs still need them available before
  // the device goes offline.
  critical.add('./assets/vendor/pdf-lib/pdf-lib.min.js?v=1.17.1');
  critical.add('./assets/vendor/pdf-fontkit/fontkit.umd.min.js?v=1.1.1');
  // Document import is a local-first workflow too. Precache the exact vendored
  // parser bytes so the first DOCX/XLSX import works after installation even
  // when the device has gone offline; neither parser may depend on having been
  // exercised once while online.
  optional.add('./assets/vendor/office/mammoth.browser.min.js?v=1.8.0');
  optional.add('./assets/vendor/office/xlsx.full.min.js?v=0.18.5');
  for (const item of critical) optional.delete(item);
  const featureSource = readFileSync(resolve(root, 'src/config/feature-manifest.js'), 'utf8');
  const sandbox = {};
  vm.runInNewContext(featureSource, sandbox, { filename: 'feature-manifest.js' });
  const lazy = new Set();
  Object.values(sandbox.SUTRA_FEATURE_MANIFEST || {}).forEach((feature) => {
    [...(feature.scripts || []), ...(feature.styles || [])].forEach((asset) => {
      const reference = normalizeLocalReference(asset);
      if (reference) lazy.add(reference);
    });
  });
  for (const item of critical) lazy.delete(item);
  for (const item of optional) lazy.delete(item);
  return {
    schemaVersion: 1,
    shell: `./${shellFile}`,
    critical: [...critical].sort(),
    optional: [...optional].sort(),
    lazy: [...lazy].sort()
  };
}

const manifest = collectReferences();
const json = `${JSON.stringify(manifest, null, 2)}\n`;
const js = `/* Generated by scripts/generate-asset-manifest.mjs. Do not edit. */\n` +
  `(function (scope) { scope.SUTRA_ASSET_MANIFEST = Object.freeze(${JSON.stringify(manifest, null, 2)}); })(typeof self !== 'undefined' ? self : globalThis);\n`;

const jsonPath = resolve(root, 'src/config/asset-manifest.generated.json');
const jsPath = resolve(root, 'src/config/asset-manifest.generated.js');
if (process.argv.includes('--check')) {
  const currentJson = readFileSync(jsonPath, 'utf8');
  const currentJs = readFileSync(jsPath, 'utf8');
  if (currentJson !== json || currentJs !== js) {
    console.error('Asset manifest is stale. Run npm run assets:generate.');
    process.exit(1);
  }
} else {
  writeFileSync(jsonPath, json);
  writeFileSync(jsPath, js);
}
console.log(`Asset manifest generated: ${manifest.critical.length} critical, ${manifest.optional.length} optional, ${manifest.lazy.length} lazy.`);
